// BuildListPayload builds the payload for the user list endpoint from CLI
// flags.
func BuildListPayload(userListPage string, userListPageSize string, userListSortBy string, userListSortOrder string, userListEmailFilter string, userListStatusFilter string, userListUserTypeFilter string) (*user.ListPayload, error) {
	var err error
	var page uint
	{
		if userListPage != "" {
			var v uint64
			v, err = strconv.ParseUint(userListPage, 10, strconv.IntSize)
			page = uint(v)
			if err != nil {
				return nil, fmt.Errorf("invalid value for page, must be UINT")
			}
			if page < 1 {
				err = goa.MergeErrors(err, goa.InvalidRangeError("page", page, 1, true))
			}
			if err != nil {
				return nil, err
			}
		}
	}
	var pageSize uint
	{
		if userListPageSize != "" {
			var v uint64
			v, err = strconv.ParseUint(userListPageSize, 10, strconv.IntSize)
			pageSize = uint(v)
			if err != nil {
				return nil, fmt.Errorf("invalid value for pageSize, must be UINT")
			}
			if pageSize < 1 {
				err = goa.MergeErrors(err, goa.InvalidRangeError("page_size", pageSize, 1, true))
			}
			if pageSize > 100 {
				err = goa.MergeErrors(err, goa.InvalidRangeError("page_size", pageSize, 100, false))
			}
			if err != nil {
				return nil, err
			}
		}
	}
	var sortBy *string
	{
		if userListSortBy != "" {
			sortBy = &userListSortBy
		}
	}
	var sortOrder string
	{
		if userListSortOrder != "" {
			sortOrder = userListSortOrder
			if !(sortOrder == "asc" || sortOrder == "desc") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("sort_order", sortOrder, []any{"asc", "desc"}))
			}
			if err != nil {
				return nil, err
			}
		}
	}
	var emailFilter *string
	{
		if userListEmailFilter != "" {
			emailFilter = &userListEmailFilter
		}
	}
	var statusFilter *string
	{
		if userListStatusFilter != "" {
			statusFilter = &userListStatusFilter
			if !(*statusFilter == "ACTIVE" || *statusFilter == "INACTIVE" || *statusFilter == "LOCKED" || *statusFilter == "SUSPENDED" || *statusFilter == "PENDING_VERIFICATION" || *statusFilter == "EXPIRED") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("status_filter", *statusFilter, []any{"ACTIVE", "INACTIVE", "LOCKED", "SUSPENDED", "PENDING_VERIFICATION", "EXPIRED"}))
			}
			if err != nil {
				return nil, err
			}
		}
	}
	var userTypeFilter *string
	{
		if userListUserTypeFilter != "" {
			userTypeFilter = &userListUserTypeFilter
			if !(*userTypeFilter == "INTERNAL" || *userTypeFilter == "CUSTOMER" || *userTypeFilter == "VENDOR" || *userTypeFilter == "PARTNER" || *userTypeFilter == "API" || *userTypeFilter == "SERVICE" || *userTypeFilter == "ADMIN") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("user_type_filter", *userTypeFilter, []any{"INTERNAL", "CUSTOMER", "VENDOR", "PARTNER", "API", "SERVICE", "ADMIN"}))
			}
			if err != nil {
				return nil, err
			}
		}
	}
	v := &user.ListPayload{}
	v.Page = page
	v.PageSize = pageSize
	v.SortBy = sortBy
	v.SortOrder = sortOrder
	v.EmailFilter = emailFilter
	v.StatusFilter = statusFilter
	v.UserTypeFilter = userTypeFilter

	return v, nil
}

